sp_widget.client_script:
api.controller = function($scope) {

    var c = this;


    /* =========================================================
       DEFAULT SECTION
       ========================================================= */

    c.currentPage = 'overview';


    /* =========================================================
       RECORD FORM
       ========================================================= */

    c.showRecordForm = false;
    c.selectedRecord = null;

    c.savingRecord = false;

    c.formError = '';
    c.formSuccess = '';

    c.showNotesField = false;
    c.notesRequired = false;


    /* =========================================================
       FILTERS
       ========================================================= */

    c.assignmentFilters = {
        useCase: '',
        priority: ''
    };


    /* =========================================================
       FILTERED ASSIGNMENTS
       ========================================================= */

    c.filteredAssignments =
        angular.copy(
            c.data.myAssignments || []
        );


    /* =========================================================
       CHANGE PAGE
       ========================================================= */

    c.changePage = function(page) {

        c.currentPage = page;

        c.showRecordForm = false;
        c.selectedRecord = null;

        c.formError = '';
        c.formSuccess = '';

        c.savingRecord = false;
    };


    /* =========================================================
       GET RECORD
       ========================================================= */

    c.getRecord = function(sysId) {

        if (
            !sysId ||
            !c.data.records ||
            !c.data.records[sysId]
        ) {

            return null;
        }

        return c.data.records[sysId];
    };


    /* =========================================================
       OPEN RECORD
       ========================================================= */

    c.openRecord = function(sysId) {

        c.formError = '';
        c.formSuccess = '';

        var record =
            c.getRecord(sysId);


        if (!record) {

            c.formError =
                'Unable to load the selected record.';

            return;
        }


        c.selectedRecord =
            angular.copy(record);


        /* -----------------------------------------------------
           DEFAULT APPROVAL
           ----------------------------------------------------- */

        if (
            !c.selectedRecord.approval
        ) {

            c.selectedRecord.approval =
                'requested';
        }


        c.selectedRecord.approval =
            String(
                c.selectedRecord.approval
            ).toLowerCase();


        /* -----------------------------------------------------
           UPDATE NOTES VISIBILITY
           ----------------------------------------------------- */

        c.updateNotesVisibility();


        /* -----------------------------------------------------
           SHOW FORM
           ----------------------------------------------------- */

        c.showRecordForm = true;


        /* -----------------------------------------------------
           SCROLL TO FORM
           ----------------------------------------------------- */

        setTimeout(
            function() {

                var element =
                    document.getElementById(
                        'manager-record-form'
                    );

                if (element) {

                    element.scrollIntoView({
                        behavior: 'smooth',
                        block: 'start'
                    });
                }

            },
            100
        );
    };


    /* =========================================================
       ACCEPT RECORD
       ========================================================= */

    c.acceptRecord = function(sysId) {

        c.formError = '';
        c.formSuccess = '';

        var record =
            c.getRecord(sysId);


        if (!record) {

            c.formError =
                'Unable to load the selected record.';

            return;
        }


        c.selectedRecord =
            angular.copy(record);


        /* -----------------------------------------------------
           MANAGER ACCEPTS RECORD
           ----------------------------------------------------- */

        c.selectedRecord.approval =
            'approved';


        /* -----------------------------------------------------
           UPDATE NOTES VISIBILITY
           ----------------------------------------------------- */

        c.updateNotesVisibility();


        /* -----------------------------------------------------
           SHOW FORM
           ----------------------------------------------------- */

        c.showRecordForm = true;


        /* -----------------------------------------------------
           SCROLL TO FORM
           ----------------------------------------------------- */

        setTimeout(
            function() {

                var element =
                    document.getElementById(
                        'manager-record-form'
                    );

                if (element) {

                    element.scrollIntoView({
                        behavior: 'smooth',
                        block: 'start'
                    });
                }

            },
            100
        );
    };


    /* =========================================================
       NOTES VISIBILITY
       ========================================================= */

    c.updateNotesVisibility = function() {

        if (!c.selectedRecord) {

            c.showNotesField = false;
            c.notesRequired = false;

            return;
        }


        var approval =
            String(
                c.selectedRecord.approval || ''
            ).toLowerCase();


        if (
            approval === 'approved' ||
            approval === 'rejected'
        ) {

            c.showNotesField = true;
            c.notesRequired = true;

        } else {

            c.showNotesField = false;
            c.notesRequired = false;
        }
    };


    /* =========================================================
       APPROVAL CHANGE
       ========================================================= */

    c.approvalChanged = function() {

        c.updateNotesVisibility();
    };


    /* =========================================================
       SAVE RECORD
       ========================================================= */

    c.saveRecord = function() {

        /* -----------------------------------------------------
           CHECK RECORD
           ----------------------------------------------------- */

        if (!c.selectedRecord) {

            c.formError =
                'No record selected.';

            return;
        }


        /* -----------------------------------------------------
           CLEAR OLD MESSAGES
           ----------------------------------------------------- */

        c.formError = '';
        c.formSuccess = '';


        /* -----------------------------------------------------
           GET APPROVAL
           ----------------------------------------------------- */

        var approval =
            String(
                c.selectedRecord.approval || ''
            ).toLowerCase();


        /* -----------------------------------------------------
           VALIDATE APPROVAL
           ----------------------------------------------------- */

        if (
            approval !== 'requested' &&
            approval !== 'approved' &&
            approval !== 'rejected'
        ) {

            c.formError =
                'Please select a valid approval status.';

            return;
        }


        /* -----------------------------------------------------
           GET NOTES
           ----------------------------------------------------- */

        var notes =
            String(
                c.selectedRecord.notes || ''
            );


        /* -----------------------------------------------------
           NOTES REQUIRED FOR APPROVED / REJECTED
           ----------------------------------------------------- */

        if (
            (
                approval === 'approved' ||
                approval === 'rejected'
            ) &&
            notes.trim() === ''
        ) {

            c.formError =
                'Notes are mandatory when approval is Approved or Rejected.';

            return;
        }


        /* -----------------------------------------------------
           START SAVING
           ----------------------------------------------------- */

        c.savingRecord = true;


        /* -----------------------------------------------------
           SAVE EXISTING RECORD
           ----------------------------------------------------- */

        c.server.get({

            action: 'saveRecord',

            sys_id:
                c.selectedRecord.sys_id,

            approval:
                approval,

            notes:
                notes

        }).then(

            function(response) {

                /* =============================================
                   CHECK SERVER ERROR
                   ============================================= */

                if (
                    response.data &&
                    response.data.saveError
                ) {

                    c.formError =
                        response.data.saveError;

                    c.savingRecord = false;

                    return;
                }


                /* =============================================
                   UPDATE CURRENT DASHBOARD DATA
                   ============================================= */

                if (response.data) {

                    angular.extend(
                        c.data,
                        response.data
                    );
                }


                /* =============================================
                   REFRESH FILTERED ASSIGNMENTS
                   ============================================= */

                c.filteredAssignments =
                    angular.copy(
                        c.data.myAssignments || []
                    );


                c.applyAssignmentFilters();


                /* =============================================
                   SUCCESS
                   ============================================= */

                if (
                    response.data &&
                    response.data.saveSuccess
                ) {

                    c.formSuccess =
                        'Record updated successfully.';


                    /* -----------------------------------------
                       CLOSE FORM AFTER SUCCESS MESSAGE
                       ----------------------------------------- */

                    setTimeout(
                        function() {

                            $scope.$apply(
                                function() {

                                    c.closeRecordForm();

                                }
                            );

                        },
                        700
                    );
                }


                c.savingRecord = false;
            },


            /* =================================================
               SERVER REQUEST ERROR
               ================================================= */

            function() {

                c.formError =
                    'Something went wrong while saving the record.';

                c.savingRecord = false;
            }
        );
    };


    /* =========================================================
       CLOSE RECORD FORM
       ========================================================= */

    c.closeRecordForm = function() {

        c.showRecordForm = false;

        c.selectedRecord = null;

        c.formError = '';
        c.formSuccess = '';

        c.savingRecord = false;

        c.showNotesField = false;
        c.notesRequired = false;
    };


    /* =========================================================
       ASSIGNMENT FILTER
       ========================================================= */

    c.applyAssignmentFilters =
        function() {

            c.filteredAssignments = [];


            var assignments =
                c.data.myAssignments || [];


            for (
                var i = 0;
                i < assignments.length;
                i++
            ) {

                var sysId =
                    assignments[i];


                var record =
                    c.data.records[sysId];


                if (!record) {
                    continue;
                }


                /* ---------------------------------------------
                   USE CASE FILTER
                   --------------------------------------------- */

                var useCaseMatch = true;


                if (
                    c.assignmentFilters.useCase
                ) {

                    useCaseMatch =
                        record.use_case ===
                        c.assignmentFilters.useCase;


                    /* -----------------------------------------
                       DISPLAY VALUE FALLBACK
                       ----------------------------------------- */

                    if (!useCaseMatch) {

                        useCaseMatch =
                            record.use_case_display ===
                            c.assignmentFilters.useCase;
                    }
                }


                /* ---------------------------------------------
                   PRIORITY FILTER
                   --------------------------------------------- */

                var priorityMatch = true;


                if (
                    c.assignmentFilters.priority
                ) {

                    priorityMatch =
                        record.current_priority ===
                        c.assignmentFilters.priority;


                    /* -----------------------------------------
                       DISPLAY VALUE FALLBACK
                       ----------------------------------------- */

                    if (!priorityMatch) {

                        priorityMatch =
                            record.current_priority_display ===
                            c.assignmentFilters.priority;
                    }
                }


                /* ---------------------------------------------
                   ADD MATCHING RECORD
                   --------------------------------------------- */

                if (
                    useCaseMatch &&
                    priorityMatch
                ) {

                    c.filteredAssignments.push(
                        sysId
                    );
                }
            }
        };


    /* =========================================================
       CLEAR FILTER
       ========================================================= */

    c.clearAssignmentFilters =
        function() {

            c.assignmentFilters = {
                useCase: '',
                priority: ''
            };


            c.filteredAssignments =
                angular.copy(
                    c.data.myAssignments || []
                );
        };


    /* =========================================================
       REPORT WIDTH
       ========================================================= */

    c.getReportWidth =
        function(count, collection) {

            if (
                !collection ||
                collection.length === 0
            ) {

                return 0;
            }


            var max = 0;


            for (
                var i = 0;
                i < collection.length;
                i++
            ) {

                var currentCount =
                    parseInt(
                        collection[i].count,
                        10
                    ) || 0;


                if (
                    currentCount > max
                ) {

                    max = currentCount;
                }
            }


            if (max === 0) {
                return 0;
            }


            return (
                (count / max) * 100
            );
        };


    /* =========================================================
       DOWNLOAD REPORT
       ========================================================= */

    c.downloadReport =
        function() {

            alert(
                'Download Report functionality will be configured later.'
            );
        };


    /* =========================================================
       HORIZONTAL DRAG
       ========================================================= */

    c.startDrag =
        function(event) {

            var table =
                event.currentTarget;


            table.classList.add(
                'is-dragging'
            );


            table.startX =
                event.pageX;


            table.scrollLeftStart =
                table.scrollLeft;
        };


    c.dragMove =
        function(event) {

            var table =
                event.currentTarget;


            if (
                !table.classList.contains(
                    'is-dragging'
                )
            ) {

                return;
            }


            var distance =
                event.pageX -
                table.startX;


            table.scrollLeft =
                table.scrollLeftStart -
                distance;
        };


    c.stopDrag =
        function(event) {

            var table =
                event.currentTarget;


            table.classList.remove(
                'is-dragging'
            );
        };


    /* =========================================================
       INITIAL FILTER
       ========================================================= */

    c.clearAssignmentFilters();

};

sp_widget.css:
/* =========================================================
   MANAGER DASHBOARD
   ========================================================= */

.manager-dashboard {
    display: flex;
    width: 100%;
    min-height: 100vh;
    background: #f5f7f8;
    color: #263b39;
    font-family: Arial, sans-serif;
}


/* =========================================================
   SIDEBAR
   ========================================================= */

.manager-sidebar {
    width: 245px;
    min-width: 245px;
    background: #1E293B;
    color: #ffffff;
    min-height: 100vh;
    padding: 22px 14px;
    box-sizing: border-box;
    border-right: 1px solid #334155;
}


.manager-sidebar-brand {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 8px 10px 28px;
    border-bottom: 1px solid rgba(255,255,255,0.12);
}


.manager-brand-icon {
    width: 42px;
    height: 42px;
    border-radius: 50%;
    background: #2563EB;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 700;
    color: #FFFFFF;
    border: 2px solid #60A5FA;
    box-shadow: 0 5px 12px rgba(37, 99, 235, 0.30);
}


.manager-brand-title {
    font-size: 16px;
    font-weight: 700;
    color: #FFFFFF;
}


.manager-brand-subtitle {
    font-size: 11px;
    color: #94A3B8;
    opacity: 1;
    margin-top: 4px;
}


/* =========================================================
   NAVIGATION
   ========================================================= */

.manager-navigation {
    padding-top: 20px;
}


.manager-nav-item {
    width: 100%;
    border: none;
    background: transparent;
    color: #CBD5E1;
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 13px 14px;
    border-radius: 8px;
    margin-bottom: 6px;
    cursor: pointer;
    text-align: left;
    font-size: 14px;
    transition: 0.2s ease;
}


.manager-nav-item:hover {
    background: #334155;
    color: #FFFFFF;
}


.manager-nav-item.active {
    background: #2563EB;
    color: #FFFFFF;
    font-weight: 700;
}


.manager-nav-icon {
    width: 22px;
    text-align: center;
    font-size: 17px;
}


/* =========================================================
   CONTENT
   ========================================================= */

.manager-content {
    flex: 1;
    min-width: 0;
    padding: 30px;
    box-sizing: border-box;
}


.manager-page {
    width: 100%;
}


.manager-page-header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 20px;
    margin-bottom: 25px;
}


.manager-page-header h1 {
    margin: 0;
    font-size: 28px;
    color: #123c3a;
}


.manager-page-header p {
    margin: 7px 0 0;
    color: #6a7977;
    font-size: 14px;
}


/* =========================================================
   DOWNLOAD BUTTON
   ========================================================= */

.manager-download-btn {
    border: none;
    background: #123c3a;
    color: #ffffff;
    padding: 11px 17px;
    border-radius: 7px;
    cursor: pointer;
    font-size: 13px;
    font-weight: 600;
}


.manager-download-btn:hover {
    background: #0d302e;
}


.manager-download-btn span {
    margin-right: 6px;
}


/* =========================================================
   KPI
   ========================================================= */

.manager-kpi-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 18px;
    margin-bottom: 24px;
}


.manager-kpi-card {
    background: #ffffff;
    border: 1px solid #dce5e1;
    border-radius: 10px;
    padding: 21px;
    display: flex;
    gap: 15px;
    align-items: center;
    box-shadow: 0 2px 8px rgba(18,60,58,0.04);
}


.manager-kpi-icon {
    width: 45px;
    height: 45px;
    border-radius: 9px;
    background: #e8f0ed;
    color: #123c3a;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 20px;
    font-weight: 700;
}


.manager-kpi-label {
    font-size: 13px;
    color: #667674;
    margin-bottom: 4px;
}


.manager-kpi-value {
    font-size: 27px;
    line-height: 1.1;
    font-weight: 700;
    color: #123c3a;
}


.manager-kpi-description {
    margin-top: 5px;
    font-size: 11px;
    color: #8a9694;
}


/* =========================================================
   SECTION CARD
   ========================================================= */

.manager-section-card {
    background: #ffffff;
    border: 1px solid #dce5e1;
    border-radius: 10px;
    margin-bottom: 24px;
    overflow: hidden;
    box-shadow: 0 2px 8px rgba(18,60,58,0.04);
}


.manager-section-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 15px;
    padding: 19px 21px;
    border-bottom: 1px solid #e5ebe8;
}


.manager-section-header h2 {
    margin: 0;
    font-size: 17px;
    color: #123c3a;
}


.manager-section-header p {
    margin: 5px 0 0;
    color: #788583;
    font-size: 12px;
}


.manager-link-btn {
    border: none;
    background: transparent;
    color: #123c3a;
    font-weight: 700;
    cursor: pointer;
}


/* =========================================================
   TABLE
   ========================================================= */

.manager-table-wrapper {
    width: 100%;
    overflow-x: auto;
    overflow-y: hidden;
    cursor: grab;
}


.manager-table-wrapper.is-dragging {
    cursor: grabbing;
    user-select: none;
}


.manager-table {
    border-collapse: collapse;
    min-width: 1750px;
    width: 100%;
}


.manager-table th {
    background: #f1f5f3;
    color: #536563;
    font-size: 11px;
    font-weight: 700;
    text-align: left;
    padding: 12px 14px;
    white-space: nowrap;
    border-bottom: 1px solid #dce5e1;
}


.manager-table td {
    padding: 13px 14px;
    border-bottom: 1px solid #edf1ef;
    font-size: 12px;
    color: #455552;
    white-space: nowrap;
    vertical-align: middle;
}


.manager-table tbody tr:hover {
    background: #fafcfa;
}


.manager-open-btn {
    border: 1px solid #123c3a;
    background: #ffffff;
    color: #123c3a;
    border-radius: 6px;
    padding: 7px 11px;
    font-size: 11px;
    font-weight: 700;
    cursor: pointer;
    white-space: nowrap;
}


.manager-open-btn:hover {
    background: #123c3a;
    color: #ffffff;
}


.manager-empty {
    text-align: center !important;
    padding: 35px !important;
    color: #879391 !important;
}


/* =========================================================
   FILTERS
   ========================================================= */

.manager-filter-card {
    display: flex;
    align-items: flex-end;
    gap: 16px;
    flex-wrap: wrap;
    background: #ffffff;
    border: 1px solid #dce5e1;
    border-radius: 10px;
    padding: 18px;
    margin-bottom: 20px;
}


.manager-filter-group {
    display: flex;
    flex-direction: column;
    gap: 6px;
    min-width: 210px;
}


.manager-filter-group label {
    font-size: 11px;
    color: #5f706d;
    font-weight: 700;
}


.manager-filter-group select {
    min-width: 210px;
    padding: 9px 10px;
    border: 1px solid #cfdad6;
    border-radius: 6px;
    background: #ffffff;
    color: #334643;
    outline: none;
}


.manager-filter-group select:focus {
    border-color: #123c3a;
}


.manager-clear-btn {
    border: 1px solid #cbd6d2;
    background: #ffffff;
    color: #536563;
    padding: 9px 14px;
    border-radius: 6px;
    cursor: pointer;
    font-size: 12px;
}


.manager-clear-btn:hover {
    background: #f2f5f4;
}


/* =========================================================
   STAFF PERFORMANCE
   ========================================================= */

.manager-staff-grid {
    padding: 20px;
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 12px;
}


.manager-staff-card {
    display: flex;
    align-items: center;
    gap: 12px;
    border: 1px solid #e0e7e4;
    border-radius: 8px;
    padding: 14px;
    background: #fafcfb;
}


.manager-staff-avatar {
    width: 38px;
    height: 38px;
    border-radius: 50%;
    background: #e8f0ed;
    color: #123c3a;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 700;
}


.manager-staff-name {
    color: #123c3a;
    font-weight: 700;
    font-size: 13px;
}


.manager-staff-role {
    color: #7b8986;
    font-size: 11px;
    margin-top: 3px;
}


/* =========================================================
   REPORTS
   ========================================================= */

.manager-report-card {
    background: #ffffff;
    border: 1px solid #dce5e1;
    border-radius: 10px;
    margin-bottom: 20px;
    padding: 20px;
    box-shadow: 0 2px 8px rgba(18,60,58,0.04);
}


.manager-report-header {
    margin-bottom: 20px;
}


.manager-report-header h2 {
    margin: 0;
    color: #123c3a;
    font-size: 17px;
}


.manager-report-header p {
    margin: 5px 0 0;
    color: #7a8886;
    font-size: 12px;
}


.manager-report-list {
    display: flex;
    flex-direction: column;
    gap: 13px;
}


.manager-report-row {
    display: grid;
    grid-template-columns: 180px 1fr 50px;
    align-items: center;
    gap: 15px;
}


.manager-report-label {
    font-size: 12px;
    color: #52625f;
}


.manager-report-bar-container {
    height: 9px;
    background: #edf2f0;
    border-radius: 20px;
    overflow: hidden;
}


.manager-report-bar {
    height: 100%;
    background: #123c3a;
    border-radius: 20px;
    min-width: 2px;
}


.manager-report-count {
    text-align: right;
    font-size: 12px;
    font-weight: 700;
    color: #123c3a;
}


/* =========================================================
   RECORD FORM
   ========================================================= */

.manager-record-form {
    background: #ffffff;
    border: 1px solid #dce5e1;
    border-radius: 10px;
    margin-top: 25px;
    box-shadow: 0 4px 15px rgba(18,60,58,0.06);
    overflow: hidden;
}


.manager-form-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    padding: 21px;
    border-bottom: 1px solid #e2e9e6;
}


.manager-form-header h2 {
    margin: 0;
    color: #123c3a;
    font-size: 19px;
}


.manager-form-header p {
    margin: 5px 0 0;
    color: #7b8986;
    font-size: 12px;
}


.manager-close-btn {
    border: none;
    background: #f1f4f3;
    color: #536563;
    width: 34px;
    height: 34px;
    border-radius: 7px;
    font-size: 21px;
    cursor: pointer;
}


.manager-close-btn:hover {
    background: #e5ebe8;
}


/* =========================================================
   FORM MESSAGES
   ========================================================= */

.manager-form-error {
    margin: 18px 21px 0;
    padding: 11px 13px;
    background: #fff2f0;
    border: 1px solid #f0c7c1;
    color: #9a4034;
    border-radius: 6px;
    font-size: 12px;
}


.manager-form-success {
    margin: 18px 21px 0;
    padding: 11px 13px;
    background: #edf8f2;
    border: 1px solid #c7e3d2;
    color: #31734b;
    border-radius: 6px;
    font-size: 12px;
}


/* =========================================================
   FORM GRID
   ========================================================= */

.manager-form-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 17px;
    padding: 22px;
}


.manager-form-field {
    display: flex;
    flex-direction: column;
    gap: 7px;
}


.manager-form-field-wide {
    grid-column: 1 / -1;
}


.manager-form-field label {
    font-size: 11px;
    color: #586966;
    font-weight: 700;
}


.manager-form-field input,
.manager-form-field select,
.manager-form-field textarea {
    width: 100%;
    box-sizing: border-box;
    border: 1px solid #d2dcd8;
    border-radius: 6px;
    padding: 10px 11px;
    font-size: 12px;
    color: #344541;
    background: #ffffff;
    outline: none;
}


.manager-form-field input:focus,
.manager-form-field select:focus,
.manager-form-field textarea:focus {
    border-color: #123c3a;
}


.manager-form-field input[readonly],
.manager-form-field textarea[readonly] {
    background: #f5f7f6;
    color: #667571;
}


.manager-form-field textarea {
    min-height: 85px;
    resize: vertical;
}


.manager-required {
    color: #b33c2f;
}


/* =========================================================
   FORM ACTIONS
   ========================================================= */

.manager-form-actions {
    display: flex;
    justify-content: flex-end;
    gap: 10px;
    padding: 18px 21px;
    border-top: 1px solid #e2e9e6;
    background: #fafcfb;
}


.manager-cancel-btn {
    border: 1px solid #ccd7d3;
    background: #ffffff;
    color: #53635f;
    border-radius: 6px;
    padding: 10px 16px;
    cursor: pointer;
    font-size: 12px;
    font-weight: 600;
}


.manager-save-btn {
    border: none;
    background: #123c3a;
    color: #ffffff;
    border-radius: 6px;
    padding: 10px 17px;
    cursor: pointer;
    font-size: 12px;
    font-weight: 700;
}


.manager-save-btn:hover {
    background: #0d302e;
}


.manager-save-btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1100px) {

    .manager-sidebar {
        width: 215px;
        min-width: 215px;
    }

    .manager-content {
        padding: 22px;
    }

    .manager-kpi-grid {
        grid-template-columns: 1fr;
    }

}


@media (max-width: 760px) {

    .manager-dashboard {
        display: block;
    }

    .manager-sidebar {
        width: 100%;
        min-width: 100%;
        min-height: auto;
        border-right: 0;
        border-bottom: 1px solid #334155;
    }

    .manager-navigation {
        display: flex;
        overflow-x: auto;
        gap: 6px;
    }

    .manager-nav-item {
        min-width: max-content;
        width: auto;
    }

    .manager-page-header {
        flex-direction: column;
    }

    .manager-form-grid {
        grid-template-columns: 1fr;
    }

    .manager-form-field-wide {
        grid-column: auto;
    }

    .manager-staff-grid {
        grid-template-columns: 1fr;
    }

    .manager-report-row {
        grid-template-columns: 1fr;
        gap: 6px;
    }

    .manager-report-count {
        text-align: left;
    }

}

sp_widget.script:
(function() {

    /* =========================================================
       TABLES
       ========================================================= */

    var taskTable = 'x_snc_campus_foo_1_complain_tasks';
    var userGroupMemberTable = 'sys_user_grmember';
    var choiceTable = 'sys_choice';


    /* =========================================================
       GROUP SYS IDS
       ========================================================= */

    var managerGroup = '9374d15fdd1f03107f44143a6accf88d';
    var staffGroup = '4f04d11fdd1f03107f44143a6accf8c1';
    var adminGroup = '1754d95bdd1f03107f44143a6accf85b';


    /* =========================================================
       DEFAULT DATA
       ========================================================= */

    data.totalRequests = 0;
    data.resolvedRequests = 0;
    data.pendingRequests = 0;

    data.records = {};

    data.recentAssignments = [];
    data.myAssignments = [];
    data.history = [];

    data.staffPerformance = [];
    data.totalStaff = 0;
    data.assignedRequests = 0;
    data.pendingApprovals = 0;

    data.topPendingProblems = [];

    data.useCaseChoices = [];
    data.priorityChoices = [];

    data.saveSuccess = false;
    data.saveError = '';


    /* =========================================================
       HELPER
       ========================================================= */

    function getValue(gr, field) {
        return gr.getValue(field) || '';
    }

    function getDisplayValue(gr, field) {
        return gr.getDisplayValue(field) || '';
    }


    /* =========================================================
       LOAD TASK RECORD
       ========================================================= */

    function addTaskRecord(gr) {

        var sysId = gr.getUniqueValue();

        data.records[sysId] = {
            sys_id: sysId,

            number: getDisplayValue(gr, 'number'),

            use_case: getValue(gr, 'use_case'),
            use_case_display: getDisplayValue(gr, 'use_case'),

            current_priority: getValue(gr, 'current_priority'),
            current_priority_display: getDisplayValue(gr, 'current_priority'),

            student_count: getValue(gr, 'student_count'),

            state: getValue(gr, 'state'),
            state_display: getDisplayValue(gr, 'state'),

            assignment_group: getValue(gr, 'assignment_group'),
            assignment_group_display: getDisplayValue(gr, 'assignment_group'),

            problem_type: getValue(gr, 'problem_type'),
            problem_type_display: getDisplayValue(gr, 'problem_type'),

            short_description: getValue(gr, 'short_description'),

            approval: getValue(gr, 'approval'),
            approval_display: getDisplayValue(gr, 'approval'),

            use_case_number: getValue(gr, 'use_case_number'),

            mess_hall: getValue(gr, 'mess_hall'),
            mess_hall_display: getDisplayValue(gr, 'mess_hall'),

            meal_type: getValue(gr, 'meal_type'),
            meal_type_display: getDisplayValue(gr, 'meal_type'),

            priority_reason: getValue(gr, 'priority_reason'),

            recomended_actions: getValue(gr, 'recomended_actions'),

            resolution_status: getValue(gr, 'resolution_status'),
            resolution_status_display: getDisplayValue(gr, 'resolution_status'),

            sys_updated_on: getDisplayValue(gr, 'sys_updated_on')
        };

        return sysId;
    }


    /* =========================================================
       GET ALL MANAGEMENT TASKS
       FOR MAIN OVERVIEW KPI
       ========================================================= */

    var totalGR = new GlideRecord(taskTable);

    totalGR.addQuery('assignment_group', managerGroup);
    totalGR.query();

    while (totalGR.next()) {

        data.totalRequests++;

        var totalSysId = addTaskRecord(totalGR);

        /*
         * Resolved means:
         * Management Group + Approval = Approved
         */
        if (getValue(totalGR, 'approval') == 'approved') {
            data.resolvedRequests++;
        }
    }


    /* =========================================================
       PENDING = TOTAL - RESOLVED
       ========================================================= */

    data.pendingRequests =
        data.totalRequests - data.resolvedRequests;

    if (data.pendingRequests < 0) {
        data.pendingRequests = 0;
    }


    /* =========================================================
       RECENT ASSIGNMENTS
       MANAGEMENT GROUP + REQUESTED
       TOP 5
       ========================================================= */

    var recentGR = new GlideRecord(taskTable);

    recentGR.addQuery('assignment_group', managerGroup);
    recentGR.addQuery('approval', 'requested');
    recentGR.orderByDesc('sys_created_on');
    recentGR.setLimit(5);
    recentGR.query();

    while (recentGR.next()) {

        var recentSysId = addTaskRecord(recentGR);

        data.recentAssignments.push(recentSysId);
    }


    /* =========================================================
       MY ASSIGNMENTS
       MANAGEMENT GROUP + REQUESTED
       ALL RECORDS
       ========================================================= */

    var assignmentGR = new GlideRecord(taskTable);

    assignmentGR.addQuery('assignment_group', managerGroup);
    assignmentGR.addQuery('approval', 'requested');
    assignmentGR.orderByDesc('sys_created_on');
    assignmentGR.query();

    while (assignmentGR.next()) {

        var assignmentSysId = addTaskRecord(assignmentGR);

        data.myAssignments.push(assignmentSysId);
    }


    /* =========================================================
       HISTORY
       MANAGEMENT GROUP + APPROVED OR REJECTED
       ========================================================= */

    var historyGR = new GlideRecord(taskTable);

    historyGR.addQuery('assignment_group', managerGroup);

    var historyQuery = historyGR.addQuery(
        'approval',
        'approved'
    );

    historyQuery.addOrCondition(
        'approval',
        'rejected'
    );

    historyGR.orderByDesc('sys_updated_on');
    historyGR.query();

    while (historyGR.next()) {

        var historySysId = addTaskRecord(historyGR);

        data.history.push(historySysId);
    }


    /* =========================================================
       STAFF PERFORMANCE
       ========================================================= */

    /*
     * TOTAL STAFF
     * Active users belonging to Staff Group
     */

    var staffGR = new GlideRecord(userGroupMemberTable);

    staffGR.addQuery('group', staffGroup);
    staffGR.addQuery('user.active', true);
    staffGR.query();

    while (staffGR.next()) {

        data.totalStaff++;

        if (data.staffPerformance.length < 5) {

            data.staffPerformance.push({
                sys_id: staffGR.user.toString(),
                name: staffGR.user.getDisplayValue()
            });
        }
    }


    /* =========================================================
       ASSIGNED REQUESTS
       ALL ACTIVE COMPLAINT TASKS
       ========================================================= */

    var assignedGR = new GlideRecord(taskTable);

    assignedGR.addQuery('active', true);
    assignedGR.query();

    while (assignedGR.next()) {
        data.assignedRequests++;
    }


    /* =========================================================
       PENDING APPROVALS
       STAFF OR ADMIN GROUP + REQUESTED
       ========================================================= */

    var pendingApprovalGR = new GlideRecord(taskTable);

    pendingApprovalGR.addQuery(
        'assignment_group',
        'IN',
        staffGroup + ',' + adminGroup
    );

    pendingApprovalGR.addQuery(
        'approval',
        'requested'
    );

    pendingApprovalGR.query();

    while (pendingApprovalGR.next()) {

        data.pendingApprovals++;

        /*
         * Top 10 pending records
         */
        if (data.topPendingProblems.length < 10) {

            var pendingSysId =
                addTaskRecord(pendingApprovalGR);

            data.topPendingProblems.push(
                pendingSysId
            );
        }
    }


    /* =========================================================
       USE CASE CHOICES
       ========================================================= */

    var useCaseGR = new GlideRecord(choiceTable);

    useCaseGR.addQuery('name', taskTable);
    useCaseGR.addQuery('element', 'use_case');
    useCaseGR.addQuery('inactive', false);
    useCaseGR.orderBy('sequence');
    useCaseGR.query();

    while (useCaseGR.next()) {

        data.useCaseChoices.push({
            value: useCaseGR.getValue('value'),
            label: useCaseGR.getValue('label')
        });
    }


    /* =========================================================
       PRIORITY CHOICES
       ========================================================= */

    var priorityGR = new GlideRecord(choiceTable);

    priorityGR.addQuery('name', taskTable);
    priorityGR.addQuery('element', 'current_priority');
    priorityGR.addQuery('inactive', false);
    priorityGR.orderBy('sequence');
    priorityGR.query();

    while (priorityGR.next()) {

        data.priorityChoices.push({
            value: priorityGR.getValue('value'),
            label: priorityGR.getValue('label')
        });
    }


    /* =========================================================
       REPORT DATA
       ========================================================= */

    data.reportUseCase = [];
    data.reportPriority = [];
    data.reportApproval = [];
    data.reportTime = [];


    /* =========================================================
       REPORT 1
       REQUESTS BY USE CASE
       MANAGEMENT GROUP
       ========================================================= */

    var reportUseCaseGR = new GlideAggregate(taskTable);

    reportUseCaseGR.addQuery(
        'assignment_group',
        managerGroup
    );

    reportUseCaseGR.addNotNullQuery('use_case');

    reportUseCaseGR.addAggregate(
        'COUNT',
        'use_case'
    );

    reportUseCaseGR.groupBy('use_case');

    reportUseCaseGR.orderByDesc(
        'COUNT',
        'use_case'
    );

    reportUseCaseGR.query();

    while (reportUseCaseGR.next()) {

        data.reportUseCase.push({
            label: reportUseCaseGR.getDisplayValue(
                'use_case'
            ),
            count: parseInt(
                reportUseCaseGR.getAggregate(
                    'COUNT',
                    'use_case'
                ),
                10
            )
        });
    }


    /* =========================================================
       REPORT 2
       REQUESTS BY PRIORITY
       MANAGEMENT GROUP
       ========================================================= */

    var reportPriorityGR =
        new GlideAggregate(taskTable);

    reportPriorityGR.addQuery(
        'assignment_group',
        managerGroup
    );

    reportPriorityGR.addNotNullQuery(
        'current_priority'
    );

    reportPriorityGR.addAggregate(
        'COUNT',
        'current_priority'
    );

    reportPriorityGR.groupBy(
        'current_priority'
    );

    reportPriorityGR.orderByDesc(
        'COUNT',
        'current_priority'
    );

    reportPriorityGR.query();

    while (reportPriorityGR.next()) {

        data.reportPriority.push({
            label: reportPriorityGR.getDisplayValue(
                'current_priority'
            ),
            count: parseInt(
                reportPriorityGR.getAggregate(
                    'COUNT',
                    'current_priority'
                ),
                10
            )
        });
    }


    /* =========================================================
       REPORT 3
       APPROVAL STATUS
       MANAGEMENT GROUP
       ========================================================= */

    var reportApprovalGR =
        new GlideAggregate(taskTable);

    reportApprovalGR.addQuery(
        'assignment_group',
        managerGroup
    );

    reportApprovalGR.addAggregate(
        'COUNT',
        'approval'
    );

    reportApprovalGR.groupBy(
        'approval'
    );

    reportApprovalGR.query();

    while (reportApprovalGR.next()) {

        data.reportApproval.push({
            label: reportApprovalGR.getDisplayValue(
                'approval'
            ),
            count: parseInt(
                reportApprovalGR.getAggregate(
                    'COUNT',
                    'approval'
                ),
                10
            )
        });
    }


    /* =========================================================
       REPORT 4
       REQUESTS OVER TIME
       MANAGEMENT GROUP
       ========================================================= */

    var reportTimeGR =
        new GlideAggregate(taskTable);

    reportTimeGR.addQuery(
        'assignment_group',
        managerGroup
    );

    reportTimeGR.addAggregate(
        'COUNT'
    );

    reportTimeGR.query();

    /*
     * Keep overall count here.
     * Detailed time chart can be expanded later.
     */
    if (reportTimeGR.next()) {

        data.reportTime.push({
            label: 'Total Requests',
            count: parseInt(
                reportTimeGR.getAggregate('COUNT'),
                10
            )
        });
    }


    /* =========================================================
       SAVE RECORD
       ========================================================= */

    if (input && input.action == 'saveRecord') {

        data.saveSuccess = false;
        data.saveError = '';

        if (!input.sys_id) {

            data.saveError =
                'Record sys_id is missing.';

            return;
        }

        if (!input.approval) {

            data.saveError =
                'Please select an approval status.';

            return;
        }

        if (
            input.approval != 'requested' &&
            input.approval != 'approved' &&
            input.approval != 'rejected'
        ) {

            data.saveError =
                'Invalid approval status.';

            return;
        }


        /*
         * Notes mandatory for Approved / Rejected
         */

        if (
            input.approval == 'approved' ||
            input.approval == 'rejected'
        ) {

            if (
                !input.notes ||
                input.notes.trim() == ''
            ) {

                data.saveError =
                    'Notes are mandatory when approval is Approved or Rejected.';

                return;
            }
        }


        /* =====================================================
           GET EXISTING TASK
           ===================================================== */

        var updateTask =
            new GlideRecord(taskTable);

        if (!updateTask.get(input.sys_id)) {

            data.saveError =
                'The requested task could not be found.';

            return;
        }


        /* =====================================================
           AUTHORIZATION
           ONLY MANAGEMENT GROUP
           ===================================================== */

        if (
            updateTask.getValue(
                'assignment_group'
            ) != managerGroup
        ) {

            data.saveError =
                'You are not allowed to update this task.';

            return;
        }


        /* =====================================================
           UPDATE EXISTING RECORD
           ===================================================== */

        updateTask.setValue(
            'approval',
            input.approval
        );


        if (
            input.approval == 'approved' ||
            input.approval == 'rejected'
        ) {

            updateTask.setValue(
                'active',
                false
            );

            updateTask.setValue(
                'closed_at',
                new GlideDateTime()
            );

            updateTask.setValue(
                'closed_by',
                gs.getUserID()
            );

            updateTask.setValue(
                'notes',
                input.notes
            );
        }

        updateTask.update();

        data.saveSuccess = true;

        gs.info(
            'Manager Portal updated Complaint Task: ' +
            input.sys_id
        );
    }

})();
